TLM.f("Sancti/07-27",{"officium":"S. Pantaleonis Martyris","rule":["vide C2a;","Gloria"],"fallback":"Commune/C2a","from":{"Introitus":"Commune/C2a","Lectio":"Commune/C2a","Graduale":"Commune/C2a","Tractus":"Commune/C2a","Evangelium":"Commune/C2a","Offertorium":"Commune/C2a","Secreta":"Commune/C2a","Communio":"Commune/C2a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, intercedénte beáto Pantaleóne Mártyre tuo, et a cunctis adversitátibus liberémur in córpore, et a pravis cogitatiónibus mundémur in mente."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 2:8-10; 3:10-12"},{"k":"text","la":"Caríssime: Memor esto, Dóminum Jesum Christum resurrexísse a mórtuis ex sémine David, secúndum Evangélium meum, in quo labóro usque ad víncula, quasi male óperans: sed verbum Dei non est alligátum. Ideo ómnia sustíneo propter eléctos, ut et ipsi salútem consequántur, quæ est in Christo Jesu, cum glória coelésti. Tu autem assecútus es meam doctrínam, institutiónem, propósitum, fidem, longanimitátem, dilectiónem, patiéntiam, persecutiónes, passiónes: quália mihi facta sunt Antiochíæ, Icónii et Lystris: quales persecutiónes sustínui, et ex ómnibus erípuit me Dóminus. Et omnes, qui pie volunt vívere in Christo Jesu, persecutiónem patiéntur."}],"Graduale":[{"k":"ref","la":"Ps 36:24"},{"k":"text","la":"Justus cum cecíderit, non collidétur: quia Dóminus suppónit manum suam."},{"k":"ref","la":"Ps 36:26"},{"k":"text","la":"Tota die miserétur, et cómmodat: et semen ejus in benedictióne erit. Allelúja, allelúja"},{"k":"ref","la":"Joann 8:12"},{"k":"text","la":"Qui séquitur me, non ámbulat in ténebris: sed habébit lumen vitæ ætérnæ. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:24"},{"k":"text","la":"Justus cum cecíderit, non collidétur: quia Dóminus suppónit manum suam."},{"k":"ref","la":"Ps 36:26"},{"k":"text","la":"Tota die miserétur, et cómmodat: et semen ejus in benedictióne erit."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:26-32"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nihil est opértum, quod non revelábitur; et occúltum, quod non sciétur. Quod dico vobis in ténebris, dícite in lúmine: et quod in aure audítis, prædicáte super tecta. Et nolíte timére eos, qui occídunt corpus, ánimam autem non possunt occídere; sed pótius timéte eum, qui potest et ánimam et corpus pérdere in gehénnam. Nonne duo pásseres asse véneunt: et unus ex illis non cadet super terram sine Patre vestro? Vestri autem capílli cápitis omnes numeráti sunt. Nolíte ergo timére: multis passéribus melióres estis vos. Omnis ergo, qui confitébitur me coram homínibus, confitébor et ego eum coram Patre meo, qui in coelis est."}],"Offertorium":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso: vitam pétiit a te, et tribuísti ei, allelúja."}],"Secreta":[{"k":"text","la":"Accépta sit in conspéctu tuo, Dómine, nostra devótio: et ejus nobis fiat supplicatióne salutáris, pro cujus sollemnitáte defértur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 12:26"},{"k":"text","la":"Qui mihi mínistrat, me sequátur: et ubi sum ego, illic et miníster meus erit. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedénte beáto Pantaleóne Mártyre tuo, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"866d6b75749d0039":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da zagovor blaženoga Pantaleona tvoga mučenika, oslobodi naše tijelo od svih protivština i učini da naš duh misli na ono što je dobro.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da zagovor blaženoga I., Tvoga mučenika, oslobodi naše tijelo od svih protivština, a dušu da očisti od svih zlih misli. Po G. :n.","knRef":"Kniewald 1942, str. 794–795 (snimka 398) (OCR)"},"9618e1534aadf103":{"t":"Bio ti, Gospodine, ugodan naš odani dar, i neka nam bude spasonosan po molitvi onoga o čijoj se svetkovini prikazuje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"798e670485dd4427":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom prinosu, molimo te, Gospodine, Bože naš, da po zagovoru blaženoga Pantaleona mučenika tvoga osjetimo djelovanje svetog bogoslužja koje vršimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga I., mučenika Tvoga, osjetimo djelovanje svetih tajna, koje izvršujemO'. Po G. n.","knRef":"Kniewald 1942, str. 796–797 (snimka 399) (OCR)"}}});
